DELETE FROM `page_text_locale` WHERE `ID` = 5411 AND `locale` = 'ruRU';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) VALUES
(5411, 'ruRU', 'Я — Иллисанна, дочь командира Сопротивления Курталоса Вороньей Скалы. Теперь вы уже должны знать, что мой отец мёртв. Я не единственная, кто кого-то потерял. Наша великая империя, весь наш мир горит перед нашими глазами.\n\nНичто в этой войне с Пылающим Легионом не идёт по плану. Ничто. За каждой выигранной битвой следуют два поражения. На месте каждого убитого демона появляется ещё десять.\n\nКак и мой отец, я когда-то была так уверена в победе. Так самонадеянна. Так глупа. Большинство бойцов Сопротивления до сих пор таковы. Они крепко держатся за свои архаичные методы, не желая признать, что мы не можем победить нашего врага обычными средствами. Мы сражаемся с чем-то чуждым этому миру, с чем-то, рождённым из кошмара.\n\nЕсть один эльф, который понимает это: Иллидан Штормгнев. Он знает, что для победы над демонами мы должны меняться. Мы должны принять необычные новые тактики. Если нет — мы погибнем. Всё очень просто.');
